     1	import {validateMessage} from './validation.js';
     2	
     3	// spec: specs/hal-engine-websocket-protocol/spec.md — the list_sessions frame is checked on arrival, before any store is asked.
     4	
     5	describe('validating a list_sessions frame', () => {
     6	  it('accepts a list_sessions frame, forwarding limit and before and dropping a client userId', () => {
     7	    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
     8	
     9	    const results = [
    10	      validateMessage({type: 'list_sessions'}),
    11	      validateMessage({type: 'list_sessions', limit: 0, before: {updatedAt: 1767225900000, sessionId: 's3'}}),
    12	      validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'}),
    13	    ];
    14	
    15	    expect(results).toEqual([
    16	      {valid: true, data: {type: 'list_sessions'}},
    17	      {valid: true, data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1767225900000, sessionId: 's3'}}},
    18	      {valid: true, data: {type: 'list_sessions', limit: 10, before}},
    19	    ]);
    20	  });
    21	
    22	  it('rejects a list_sessions frame whose limit or before is malformed, naming the field', () => {
    23	    const bad = [
    24	      {type: 'list_sessions', limit: 'ten'},
    25	      {type: 'list_sessions', limit: -1},
    26	      {type: 'list_sessions', limit: 1.5},
    27	      {type: 'list_sessions', before: 'not-an-object'},
    28	      {type: 'list_sessions', before: null},
    29	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
    30	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
    31	      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
    32	      {type: 'list_sessions', before: {updatedAt: Number.NaN, sessionId: 's1'}},
    33	      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    34	    ];
    35	
    36	    const errors = bad.map(frame => {
    37	      const result = validateMessage(frame);
    38	      return result.valid ? 'accepted' : /limit|before/.test(result.error);
    39	    });
