// spec: specs/hal-engine-websocket-protocol/spec.md — session_list answers list_sessions from the store, for the socket's own user.

describe('answering a list_sessions frame', () => {
  it('answers session_list from the store for the session user, with ISO dates and the frame limit and before', async () => {
    const asked: Array<[string | number, SessionListOptions | undefined]> = [];
    const store = {
      listFor: (owner: string | number, options?: SessionListOptions) => {
        asked.push([owner, options]);
        return [{sessionId: 'older', createdAt: new Date(0), updatedAt: new Date(60_000), entryCount: 2}];
      },
    } as unknown as SessionStore;
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 'current', userId: 'owner', entries: []};
    const cursor = {updatedAt: 120_000, sessionId: 'newer'};

    await createMessageHandler({} as ChatOrchestrator, store)(ws, session, {
      type: 'list_sessions',
      limit: 5,
      before: cursor,
      userId: 'intruder',
    });

    expect({asked, sent}).toEqual({
      asked: [['owner', {limit: 5, before: cursor}]],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 'older',
              createdAt: '1970-01-01T00:00:00.000Z',
              updatedAt: '1970-01-01T00:01:00.000Z',
              entryCount: 2,
            },
          ],
        },
      ],
    });
  });
});

